import cn.shed4329.onezip.i18n.I18n;
import cn.shed4329.onezip.setting.SettingsStore;
import cn.shed4329.onezip.themes.fxJava.fluent.*;
import javafx.application.Platform;
import javafx.scene.control.*;
import javafx.stage.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import static cn.shed4329.onezip.i18n.I18n.t;

/** Separate packaged-app JVM per locale, with real localized controls and isolated settings. */
class I18nProbe extends UiAcceptance {
    static void shot(Stage s,String name)throws Exception{fx(()->{s.getScene().getRoot().applyCss();s.getScene().getRoot().layout();var rendered=s.getScene().snapshot(null);int w=(int)rendered.getWidth(),h=(int)rendered.getHeight();int[] pixels=new int[w*h];rendered.getPixelReader().getPixels(0,0,w,h,javafx.scene.image.PixelFormat.getIntArgbInstance(),pixels,0,w);var bitmap=new java.awt.image.BufferedImage(w,h,java.awt.image.BufferedImage.TYPE_INT_ARGB);bitmap.setRGB(0,0,w,h,pixels,0,w);javax.imageio.ImageIO.write(bitmap,"png",output.resolve(name+".png").toFile());return null;});}
    static void finish(Stage s,String id)throws Exception{long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(30);String state="";while(System.nanoTime()<end){state=fx(()->((Label)s.getScene().lookup("#archive-status")).getText());if(state.equals(t("progress.completed"))||state.equals(t("progress.failed")))break;Thread.sleep(25);}require(state.equals(t("progress.completed")),"Task failed: "+state);fx(()->{require(((Button)s.getScene().lookup("#archive-cancel")).getText().equals(t("action.closeLegacy")),"Progress close untranslated");return null;});shot(s,id+"-progress");fx(()->{s.hide();return null;});}
    static Path pack(String format)throws Exception{Path archive=output.resolve("archive-"+format.toLowerCase(Locale.ROOT)+(format.equals("ZIP")?".zip":".7z"));fx(()->{controller.model().pageProperty().set(MainWindowModel.Page.COMPRESS);((ChoiceBox<String>)app.getScene().lookup("#compression-format")).setValue(format);((TextField)app.getScene().lookup("#compression-name")).setText(archive.getFileName().toString());((TextField)app.getScene().lookup("#compression-location")).setText(output.toString());if(format.equals("ZIP"))((TextArea)app.getScene().lookup("#compression-comment")).setText("用户说明／利用者のコメント\nPreserve exactly");require(((Button)app.getScene().lookup("#compression-start")).getText().equals(t("compress.start")),"FXML start untranslated");return null;});capture("02-compress-"+format);fx(()->{((Button)app.getScene().lookup("#compression-start")).fire();return null;});finish(progress(),format+"-compress");pass("compress-"+format,"Localized actual button and progress completion");return archive;}
    static void browse(Path archive)throws Exception{fx(()->{controller.selectArchive(archive);return null;});long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(15);while(fx(()->app.getScene().lookup("#zip-preview-progress").isVisible())){require(System.nanoTime()<end,"Listing timeout");Thread.sleep(25);}fx(()->{var table=(TableView<?>)app.getScene().lookup("#zip-entry-table");require(!table.getItems().isEmpty(),"No entries");if(archive.toString().endsWith(".zip")){var dates=table.getColumns().stream().filter(c->c.getText().equals(t("column.modified"))).findFirst().orElseThrow();String expected=java.time.Instant.parse("2024-02-29T01:23:45.123456Z").atZone(java.time.ZoneId.systemDefault()).format(java.time.format.DateTimeFormatter.ofPattern("yyyy/MM/dd HH:mm:ss"));require(expected.equals(dates.getCellData(0)),"ZIP modification date display wrong: "+dates.getCellData(0));}require(table.getColumns().getFirst().getText().equals(t("column.name")),"Header untranslated");require(((Label)app.getScene().lookup("#zip-preview-status")).getText().contains("1"),"Summary missing");return null;});capture("03-extract-"+archive.getFileName());fx(()->{for(var node:app.getScene().getRoot().lookupAll("#zip-entry-table .column-header .label"))if(node instanceof Label label&&label.lookup(".text") instanceof javafx.scene.text.Text rendered)require(label.getText().equals(rendered.getText()),"Truncated header: "+label.getText()+" -> "+rendered.getText());return null;});pass("headers","Rendered localized table headers are not elided");}
    static void unpack(Path archive)throws Exception{browse(archive);fx(()->{((Button)app.getScene().lookup("#extractAll")).fire();return null;});Stage d=fx(()->(Stage)Window.getWindows().stream().filter(w->w.isShowing()&&w.getScene()!=null&&w.getScene().lookup("#extract-destination")!=null).findFirst().orElseThrow());Path dest=output.resolve("decoded-"+archive.getFileName());
        fx(()->{var field=(TextField)d.getScene().lookup("#extract-destination");field.clear();((Button)d.getScene().lookup("#extract-start")).fire();require(((Label)d.getScene().lookup("#extract-validation")).getText().equals(t("validation.extractDirectory")),"Validation untranslated");return null;});shot(d,"04-extraction-dialog-"+archive.getFileName());fx(()->{((TextField)d.getScene().lookup("#extract-destination")).setText(dest.toString());((Button)d.getScene().lookup("#extract-start")).fire();return null;});finish(progress(),archive.getFileName()+"-extract");
        try(var files=Files.walk(input)){for(Path p:files.filter(Files::isRegularFile).toList()){Path decoded=dest.resolve(input.getFileName()).resolve(input.relativize(p));require(Files.exists(decoded)&&Files.mismatch(p,decoded)==-1,"Filename/content changed: "+p);}}
        pass("extract-"+archive.getFileName(),"Localized dialog, validation, progress and unchanged Unicode paths/bytes");
    }
    public static void main(String[] args)throws Exception{
        output=Files.createDirectories(Path.of(args[1]).toAbsolutePath());boolean restore=args.length>2;
        if(!restore)SettingsStore.shared().put("appearance.language",args[0]);I18n.initialize();require(I18n.locale().toLanguageTag().equals(args[0]),"Wrong startup locale");Platform.startup(()->Platform.setImplicitExit(false));
        try{
            app=fx(()->{var s=new Stage();var a=new MainApplication();a.start(s);var m=MainApplication.class.getDeclaredMethod("controller");m.setAccessible(true);controller=(MainWindowController)m.invoke(a);require(((Button)s.getScene().lookup("#home-compress")).getText().equals(t("action.compress")),"Home/FXML bundle not applied");return s;});capture("01-home");pass("startup-"+args[0],"FXML ResourceBundle and saved locale loaded");if(restore)return;
            input=Files.createDirectories(output.resolve("source_日本語_中文"));Files.writeString(input.resolve("保留原名_説明.txt"),"Unicode filenames and original contents\n".repeat(150));var timestamp=java.nio.file.attribute.FileTime.from(java.time.Instant.parse("2024-02-29T01:23:45.123456Z"));Files.setLastModifiedTime(input.resolve("保留原名_説明.txt"),timestamp);Files.setLastModifiedTime(input,timestamp);
            fx(()->{ThemeManager.setDark(true);controller.model().addSources(List.of(input));return null;});for(String format:List.of("ZIP","7z"))unpack(pack(format));
            Stage settings=fx(()->{((Button)app.getScene().lookup("#archive-settings")).fire();return (Stage)Window.getWindows().stream().filter(w->w!=app&&w.isShowing()&&w.getScene()!=null&&w.getScene().lookup("#settings-language")!=null).findFirst().orElseThrow();});shot(settings,"05-settings-home");
            fx(()->{((Button)settings.getScene().lookup("#settings-language")).fire();return null;});shot(settings,"06-language-settings");
            int next=(I18n.TAGS.indexOf(args[0])+1)%4;String nextTag=I18n.TAGS.get(next);
            fx(()->{var choice=(ChoiceBox<?>)settings.getScene().lookup("#settings-language-choice");require(choice.getItems().size()==4,"Four languages missing");require(choice.getSelectionModel().getSelectedIndex()==I18n.TAGS.indexOf(args[0]),"Current choice wrong");choice.getSelectionModel().select(next);((Button)settings.getScene().lookup("#settings-language-apply")).fire();require(((Label)settings.getScene().lookup("#settings-language-status")).getText().equals(t("language.saved")),"Save confirmation missing");require(I18n.locale().toLanguageTag().equals(args[0]),"Live session changed unexpectedly");return null;});pass("language-save","Actual settings save next language; current session remains consistent");
            var child=new ArrayList<String>(List.of(Path.of(System.getProperty("java.home"),"bin/java.exe").toString(),"-Dfile.encoding=UTF-8","-Donezip.settings.dir="+System.getProperty("onezip.settings.dir"),"-Donezip.settings.legacy-dir="+System.getProperty("onezip.settings.legacy-dir"),"-cp",System.getProperty("java.class.path"),"I18nProbe",nextTag,output.resolve("restart-"+nextTag).toString(),"restore"));if(System.getProperty("onezip.probe.module-path")!=null){var access=new ArrayList<String>(List.of("--module-path",System.getProperty("onezip.probe.module-path"),"--add-modules","cn.shed4329.onezip","-Donezip.probe.module-path="+System.getProperty("onezip.probe.module-path")));for(String pkg:List.of("i18n","application","themes.fxJava.fluent","themes.fxJava.fluent.component"))access.addAll(List.of("--add-exports","cn.shed4329.onezip/cn.shed4329.onezip."+pkg+"=ALL-UNNAMED"));access.addAll(List.of("--add-opens","cn.shed4329.onezip/cn.shed4329.onezip.themes.fxJava.fluent=ALL-UNNAMED"));child.addAll(1,access);}pass("restart-"+nextTag,command(child).strip());
        }catch(Throwable e){results.add("FAIL i18n: "+e);throw e;}
        finally{report();fx(()->{new ArrayList<>(Window.getWindows()).forEach(Window::hide);return null;});Platform.exit();}
    }
}
